-- 文件作用说明：建立租户客服分组、分配池、公开接入、客户资料、可靠消息及容量事务所需的数据与隔离策略。
CREATE UNIQUE INDEX IF NOT EXISTS membership_tenant_identity ON tenant_memberships(tenant_id,id);
CREATE TABLE service_spaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,is_default boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE UNIQUE INDEX one_default_space ON service_spaces(tenant_id) WHERE is_default;
CREATE TABLE agent_groups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,is_default boolean NOT NULL DEFAULT false,archived boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE UNIQUE INDEX one_default_group ON agent_groups(tenant_id) WHERE is_default;
CREATE TABLE agent_group_members(tenant_id uuid NOT NULL,group_id uuid NOT NULL,membership_id uuid NOT NULL,PRIMARY KEY(tenant_id,group_id,membership_id),FOREIGN KEY(tenant_id,group_id) REFERENCES agent_groups(tenant_id,id),FOREIGN KEY(tenant_id,membership_id) REFERENCES tenant_memberships(tenant_id,id));
CREATE TABLE routing_pools(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),service_group_id uuid NOT NULL,name text NOT NULL,algorithm text NOT NULL DEFAULT 'least_load' CHECK(algorithm IN('least_load','round_robin','manual','least_ratio','random')),assignment_mode text NOT NULL DEFAULT 'auto' CHECK(assignment_mode IN('auto','confirm')),members_mode text NOT NULL DEFAULT 'group' CHECK(members_mode IN('group','fixed')),agent_mode text NOT NULL DEFAULT 'prefer' CHECK(agent_mode IN('prefer','strict')),rr_cursor bigint NOT NULL DEFAULT 0,is_default boolean NOT NULL DEFAULT false,archived boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,service_group_id) REFERENCES agent_groups(tenant_id,id));
CREATE UNIQUE INDEX one_default_pool ON routing_pools(tenant_id) WHERE is_default;
CREATE TABLE routing_pool_members(tenant_id uuid NOT NULL,routing_pool_id uuid NOT NULL,membership_id uuid NOT NULL,weight integer NOT NULL DEFAULT 1 CHECK(weight>0),PRIMARY KEY(tenant_id,routing_pool_id,membership_id),FOREIGN KEY(tenant_id,routing_pool_id) REFERENCES routing_pools(tenant_id,id),FOREIGN KEY(tenant_id,membership_id) REFERENCES tenant_memberships(tenant_id,id));
CREATE TABLE access_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),service_space_id uuid NOT NULL,service_group_id uuid NOT NULL,routing_pool_id uuid NOT NULL,agent_id uuid,entry_key text NOT NULL UNIQUE,name text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','disabled')),channel_code text NOT NULL DEFAULT '',agent_mode text NOT NULL DEFAULT 'prefer' CHECK(agent_mode IN('prefer','strict')),allow_routing_override boolean NOT NULL DEFAULT false,page_id uuid,pinned_release_id uuid,binding_mode text NOT NULL DEFAULT 'FOLLOW_PAGE' CHECK(binding_mode IN('FOLLOW_PAGE','PIN_RELEASE')),expires_at timestamptz,is_default boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,service_space_id) REFERENCES service_spaces(tenant_id,id),FOREIGN KEY(tenant_id,service_group_id) REFERENCES agent_groups(tenant_id,id),FOREIGN KEY(tenant_id,routing_pool_id) REFERENCES routing_pools(tenant_id,id),FOREIGN KEY(tenant_id,agent_id) REFERENCES tenant_memberships(tenant_id,id));
CREATE UNIQUE INDEX one_default_link ON access_links(tenant_id) WHERE is_default;
CREATE TABLE contact_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,archived boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,name));
CREATE TABLE tag_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,archived boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,name));
CREATE TABLE tags(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),category_id uuid NOT NULL,name text NOT NULL,color text NOT NULL DEFAULT 'green',archived boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,category_id,name),FOREIGN KEY(tenant_id,category_id) REFERENCES tag_categories(tenant_id,id));
CREATE TABLE contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),display_name text NOT NULL DEFAULT '访客',remark_name text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',avatar_url text NOT NULL DEFAULT '',is_verified boolean NOT NULL DEFAULT false,category_id uuid,attributes jsonb NOT NULL DEFAULT '{}',field_sources jsonb NOT NULL DEFAULT '{}',locked_fields jsonb NOT NULL DEFAULT '[]',first_source jsonb NOT NULL DEFAULT '{}',last_source jsonb NOT NULL DEFAULT '{}',notes text NOT NULL DEFAULT '',archived boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,category_id) REFERENCES contact_categories(tenant_id,id));
CREATE TABLE contact_tags(tenant_id uuid NOT NULL,contact_id uuid NOT NULL,tag_id uuid NOT NULL,PRIMARY KEY(tenant_id,contact_id,tag_id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id),FOREIGN KEY(tenant_id,tag_id) REFERENCES tags(tenant_id,id));
CREATE TABLE contact_field_definitions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),field_key text NOT NULL,name text NOT NULL,field_type text NOT NULL CHECK(field_type IN('text','number','boolean','date','select','multiselect')),options jsonb NOT NULL DEFAULT '[]',archived boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,field_key),UNIQUE(tenant_id,id));
CREATE TABLE visitor_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),contact_id uuid NOT NULL,access_link_id uuid NOT NULL,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days',revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id),FOREIGN KEY(tenant_id,access_link_id) REFERENCES access_links(tenant_id,id));
CREATE TABLE contact_visits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),contact_id uuid NOT NULL,access_link_id uuid NOT NULL,event_id text NOT NULL,tracking jsonb NOT NULL DEFAULT '{}',context jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,event_id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id),FOREIGN KEY(tenant_id,access_link_id) REFERENCES access_links(tenant_id,id));
CREATE TABLE block_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),contact_id uuid NOT NULL,reason text NOT NULL DEFAULT '',expires_at timestamptz,revoked_at timestamptz,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id),FOREIGN KEY(tenant_id,created_by) REFERENCES tenant_memberships(tenant_id,id));
CREATE TABLE agent_runtime(tenant_id uuid NOT NULL,membership_id uuid NOT NULL,available boolean NOT NULL DEFAULT false,busy boolean NOT NULL DEFAULT false,current_load integer NOT NULL DEFAULT 0 CHECK(current_load>=0),online_until timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,membership_id),FOREIGN KEY(tenant_id,membership_id) REFERENCES tenant_memberships(tenant_id,id));
CREATE TABLE conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),service_space_id uuid NOT NULL,contact_id uuid NOT NULL,created_entry_id uuid NOT NULL,service_group_id uuid NOT NULL,routing_pool_id uuid NOT NULL,desired_agent_id uuid,agent_mode text NOT NULL DEFAULT 'prefer',status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','assigned','active','closed')),current_assignment_id uuid,current_agent_id uuid,next_event_seq bigint NOT NULL DEFAULT 0,version bigint NOT NULL DEFAULT 1,source_snapshot jsonb NOT NULL DEFAULT '{}',context jsonb NOT NULL DEFAULT '{}',priority integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz,close_reason text NOT NULL DEFAULT '',UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,service_space_id) REFERENCES service_spaces(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id),FOREIGN KEY(tenant_id,created_entry_id) REFERENCES access_links(tenant_id,id),FOREIGN KEY(tenant_id,service_group_id) REFERENCES agent_groups(tenant_id,id),FOREIGN KEY(tenant_id,routing_pool_id) REFERENCES routing_pools(tenant_id,id),FOREIGN KEY(tenant_id,current_agent_id) REFERENCES tenant_memberships(tenant_id,id),FOREIGN KEY(tenant_id,desired_agent_id) REFERENCES tenant_memberships(tenant_id,id));
CREATE UNIQUE INDEX one_open_conversation ON conversations(tenant_id,service_space_id,contact_id) WHERE status IN('queued','assigned','active');
ALTER TABLE conversations ADD COLUMN routing_attempts integer NOT NULL DEFAULT 0, ADD COLUMN rejected_agents jsonb NOT NULL DEFAULT '{}';
CREATE INDEX conversation_queue ON conversations(tenant_id,routing_pool_id,priority DESC,created_at,id) WHERE status='queued';
CREATE TABLE conversation_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,conversation_id uuid NOT NULL,membership_id uuid NOT NULL,accepted_at timestamptz,released_at timestamptz,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id),FOREIGN KEY(tenant_id,membership_id) REFERENCES tenant_memberships(tenant_id,id));
CREATE UNIQUE INDEX one_current_assignment ON conversation_assignments(tenant_id,conversation_id) WHERE released_at IS NULL;
ALTER TABLE conversations ADD FOREIGN KEY(tenant_id,current_assignment_id) REFERENCES conversation_assignments(tenant_id,id);
CREATE TABLE transfer_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,conversation_id uuid NOT NULL,from_agent_id uuid NOT NULL,target_agent_id uuid NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','accepted','rejected','expired','cancelled')),expires_at timestamptz NOT NULL DEFAULT now()+interval '30 seconds',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id),FOREIGN KEY(tenant_id,from_agent_id) REFERENCES tenant_memberships(tenant_id,id),FOREIGN KEY(tenant_id,target_agent_id) REFERENCES tenant_memberships(tenant_id,id));
CREATE UNIQUE INDEX one_pending_transfer ON transfer_requests(tenant_id,conversation_id) WHERE status='pending';
CREATE TABLE agent_capacity_holds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,conversation_id uuid NOT NULL,membership_id uuid NOT NULL,assignment_id uuid,transfer_request_id uuid,status text NOT NULL CHECK(status IN('held','active','released')),expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),released_at timestamptz,FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id),FOREIGN KEY(tenant_id,membership_id) REFERENCES tenant_memberships(tenant_id,id),FOREIGN KEY(tenant_id,assignment_id) REFERENCES conversation_assignments(tenant_id,id),FOREIGN KEY(tenant_id,transfer_request_id) REFERENCES transfer_requests(tenant_id,id));
CREATE INDEX active_capacity_holds ON agent_capacity_holds(tenant_id,membership_id) WHERE status!='released';
CREATE TABLE attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),uploader_id uuid NOT NULL,uploader_kind text NOT NULL CHECK(uploader_kind IN('visitor','agent')),file_name text NOT NULL,storage_key text NOT NULL,content_type text NOT NULL,size_bytes bigint NOT NULL,sha256 text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,conversation_id uuid NOT NULL,sender_id uuid NOT NULL,sender_kind text NOT NULL CHECK(sender_kind IN('visitor','agent','system')),client_message_id uuid NOT NULL,message_type text NOT NULL CHECK(message_type IN('text','image','file','audio')),content text NOT NULL DEFAULT '',audience text NOT NULL DEFAULT 'public' CHECK(audience IN('public','internal')),attachment_id uuid,reply_to_id uuid,event_seq bigint NOT NULL,withdrawn_at timestamptz,delivered_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,conversation_id,sender_kind,sender_id,client_message_id),FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id),FOREIGN KEY(tenant_id,attachment_id) REFERENCES attachments(tenant_id,id),FOREIGN KEY(tenant_id,reply_to_id) REFERENCES messages(tenant_id,id));
CREATE INDEX message_history ON messages(tenant_id,conversation_id,event_seq DESC);
CREATE TABLE conversation_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,conversation_id uuid NOT NULL,seq bigint NOT NULL,event_type text NOT NULL,audience text NOT NULL DEFAULT 'public' CHECK(audience IN('public','internal')),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,conversation_id,seq),FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id));
CREATE TABLE read_cursors(tenant_id uuid NOT NULL,conversation_id uuid NOT NULL,participant_id uuid NOT NULL,participant_kind text NOT NULL,last_read_seq bigint NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,conversation_id,participant_kind,participant_id),FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id));
CREATE TABLE outbox_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,event_id uuid NOT NULL,attempts integer NOT NULL DEFAULT 0,lease_until timestamptz,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,event_id),FOREIGN KEY(tenant_id,event_id) REFERENCES conversation_events(tenant_id,id));
CREATE INDEX pending_outbox ON outbox_jobs(tenant_id,created_at) WHERE completed_at IS NULL;
CREATE TABLE chat_commands(tenant_id uuid NOT NULL,actor_id uuid NOT NULL,command_key text NOT NULL,request_hash text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,actor_id,command_key));
CREATE TABLE chat_ws_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,token_hash text NOT NULL UNIQUE,contact_id uuid,membership_id uuid,expires_at timestamptz NOT NULL DEFAULT now()+interval '30 seconds',used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),CHECK((contact_id IS NULL)!=(membership_id IS NULL)),FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id),FOREIGN KEY(tenant_id,membership_id) REFERENCES tenant_memberships(tenant_id,id));

-- 对全部租户业务表启用强制行级隔离；缺失事务上下文时不返回数据。
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['service_spaces','agent_groups','agent_group_members','routing_pools','routing_pool_members','access_links','contact_categories','tag_categories','tags','contacts','contact_tags','contact_field_definitions','visitor_sessions','contact_visits','block_rules','agent_runtime','conversations','conversation_assignments','transfer_requests','agent_capacity_holds','attachments','messages','conversation_events','read_cursors','outbox_jobs','chat_commands','chat_ws_tickets'] LOOP
EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',t); END LOOP; END $$;

-- 公开定位函数只按不可猜测入口或凭证摘要查询最小定位信息，所有正文仍须在租户事务读取。
CREATE FUNCTION chat_entry_tenant(p_key text) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT tenant_id FROM public.access_links WHERE entry_key=p_key LIMIT 1 $$;
CREATE FUNCTION chat_visitor_identity(p_hash text) RETURNS TABLE(tenant_id uuid,contact_id uuid,access_link_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT s.tenant_id,s.contact_id,s.access_link_id FROM public.visitor_sessions s WHERE token_hash=p_hash AND revoked_at IS NULL AND expires_at>now() LIMIT 1 $$;
CREATE FUNCTION chat_ticket_tenant(p_hash text) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT tenant_id FROM public.chat_ws_tickets WHERE token_hash=p_hash AND used_at IS NULL AND expires_at>now() LIMIT 1 $$;
CREATE FUNCTION ensure_chat_defaults(p_tenant uuid,p_user uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$ DECLARE space_id uuid; group_id uuid; pool_id uuid; member_id uuid; BEGIN
IF nullif(current_setting('app.tenant_id',true),'')::uuid IS DISTINCT FROM p_tenant THEN RAISE EXCEPTION '租户事务上下文不匹配'; END IF;
INSERT INTO service_spaces(tenant_id,name,is_default) VALUES(p_tenant,'默认服务空间',true) ON CONFLICT(tenant_id) WHERE is_default DO NOTHING;
SELECT id INTO space_id FROM service_spaces WHERE tenant_id=p_tenant AND is_default;
INSERT INTO agent_groups(tenant_id,name,is_default) VALUES(p_tenant,'默认客服组',true) ON CONFLICT(tenant_id) WHERE is_default DO NOTHING;
SELECT id INTO group_id FROM agent_groups WHERE tenant_id=p_tenant AND is_default;
INSERT INTO routing_pools(tenant_id,service_group_id,name,is_default) VALUES(p_tenant,group_id,'默认接待池',true) ON CONFLICT(tenant_id) WHERE is_default DO NOTHING;
SELECT id INTO pool_id FROM routing_pools WHERE tenant_id=p_tenant AND is_default;
INSERT INTO access_links(tenant_id,service_space_id,service_group_id,routing_pool_id,entry_key,name,is_default) VALUES(p_tenant,space_id,group_id,pool_id,replace(gen_random_uuid()::text,'-',''),'默认咨询入口',true) ON CONFLICT(tenant_id) WHERE is_default DO NOTHING;
INSERT INTO tag_categories(tenant_id,name) VALUES(p_tenant,'默认分类') ON CONFLICT(tenant_id,name) DO NOTHING;
IF p_user IS NOT NULL THEN SELECT id INTO member_id FROM tenant_memberships WHERE tenant_id=p_tenant AND user_id=p_user AND can_serve AND NOT disabled;
IF member_id IS NOT NULL THEN INSERT INTO agent_group_members VALUES(p_tenant,group_id,member_id) ON CONFLICT DO NOTHING; INSERT INTO routing_pool_members(tenant_id,routing_pool_id,membership_id) VALUES(p_tenant,pool_id,member_id) ON CONFLICT DO NOTHING; INSERT INTO agent_runtime(tenant_id,membership_id) VALUES(p_tenant,member_id) ON CONFLICT DO NOTHING; END IF; END IF;
END $$;
COMMENT ON FUNCTION chat_entry_tenant(text) IS '按公开入口标识定位租户，不返回客户或聊天内容';
COMMENT ON FUNCTION chat_visitor_identity(text) IS '按有效访客凭证摘要解析最小身份范围';
COMMENT ON FUNCTION chat_ticket_tenant(text) IS '按未消费的短期实时票据摘要定位租户';
COMMENT ON FUNCTION ensure_chat_defaults(uuid,uuid) IS '在当前租户事务内初始化默认资源，并将指定可接待用户加入默认组池';

-- 通过受控中文词典逐列添加注释，缺少词条即失败，避免新字段遗漏。
DO $$ DECLARE t text; a record; d jsonb := '{"id":"主键编号","tenant_id":"所属租户编号","name":"显示名称","is_default":"是否默认资源","created_at":"创建时间","updated_at":"更新时间","group_id":"客服业务组编号","membership_id":"租户成员编号","service_group_id":"客服业务组编号","archived":"是否归档","algorithm":"分配主算法","assignment_mode":"接待确认模式","members_mode":"候选成员来源模式","agent_mode":"指定客服优先或严格模式","rr_cursor":"事务保护的轮询位置","routing_pool_id":"分配池编号","weight":"候选客服权重","service_space_id":"服务空间编号","agent_id":"指定客服成员编号","entry_key":"不可猜测的公开入口标识","status":"业务状态","channel_code":"来源渠道编码","allow_routing_override":"是否允许受限动态目标覆盖","page_id":"绑定的装修页面编号","pinned_release_id":"固定装修发布编号","binding_mode":"跟随页面或固定版本模式","expires_at":"有效期截止时间","category_id":"所属分类编号","color":"标签显示颜色","display_name":"客户展示姓名","remark_name":"客服备注名称","phone":"未验证的展示联系电话","avatar_url":"头像资源地址","is_verified":"客户身份是否已验证","attributes":"已登记客户自定义字段值","field_sources":"客户字段来源与可信度","locked_fields":"禁止低可信来源覆盖的字段","first_source":"客户首次来源快照","last_source":"客户最近来源快照","notes":"客户跟进备注","contact_id":"客户编号","tag_id":"标签编号","field_key":"租户内唯一字段编码","field_type":"自定义字段类型","options":"字段允许的选项","access_link_id":"接入链接编号","token_hash":"高熵凭证的不可逆摘要","revoked_at":"撤销或解除时间","event_id":"可靠事件或访问去重编号","tracking":"已清理敏感参数的来源数据","context":"本次访问或会话业务上下文","reason":"操作原因","created_by":"操作成员编号","available":"是否上班并接受新接待","busy":"是否示忙","current_load":"有效接待及预留容量占用","online_until":"在线心跳租约截止时间","created_entry_id":"创建咨询的原始入口编号","desired_agent_id":"新分配优先或严格指定的客服","current_assignment_id":"当前唯一正式接待记录","current_agent_id":"当前接待客服成员编号","next_event_seq":"最近持久事件序号","version":"会话状态并发版本","source_snapshot":"咨询创建来源与规则快照","priority":"排队优先级","closed_at":"咨询结束时间","close_reason":"咨询结束原因","conversation_id":"独立咨询编号","accepted_at":"接单确认时间","released_at":"容量或接待释放时间","from_agent_id":"原接待客服成员编号","target_agent_id":"目标接待客服成员编号","assignment_id":"关联正式接待编号","transfer_request_id":"关联待确认转接编号","uploader_id":"上传参与者编号","uploader_kind":"上传参与者类型","file_name":"仅用于展示的原始文件名","storage_key":"服务端私有存储对象键","content_type":"实际检查的媒体类型","size_bytes":"实际文件字节数","sha256":"文件内容摘要","sender_id":"发送参与者编号","sender_kind":"访客客服或系统类型","client_message_id":"发送端稳定重试去重编号","message_type":"文字图片文件或语音类型","content":"消息纯文本或显示说明","audience":"访客可见或仅内部可见范围","attachment_id":"关联有效附件编号","reply_to_id":"被引用且可见的消息编号","event_seq":"对应持久会话事件序号","withdrawn_at":"消息撤回时间","delivered_at":"授权接收终端确认时间","seq":"会话内单调递增事件序号","event_type":"事件种类","payload":"版本化事件业务载荷","participant_id":"阅读参与者编号","participant_kind":"阅读参与者类型","last_read_seq":"累计已读消息序号","attempts":"任务认领尝试次数","lease_until":"执行租约截止时间","completed_at":"任务完成时间","actor_id":"幂等操作参与者编号","command_key":"操作范围内稳定幂等键","request_hash":"幂等请求内容摘要","result":"已提交的原操作结果","used_at":"一次性实时票据消费时间"}'::jsonb;
BEGIN d:=d||'{"routing_attempts":"本轮待接单分配尝试次数","rejected_agents":"本轮拒接或超时的客服集合"}'::jsonb; FOREACH t IN ARRAY ARRAY['service_spaces','agent_groups','agent_group_members','routing_pools','routing_pool_members','access_links','contact_categories','tag_categories','tags','contacts','contact_tags','contact_field_definitions','visitor_sessions','contact_visits','block_rules','agent_runtime','conversations','conversation_assignments','transfer_requests','agent_capacity_holds','attachments','messages','conversation_events','read_cursors','outbox_jobs','chat_commands','chat_ws_tickets'] LOOP
FOR a IN SELECT attname FROM pg_attribute WHERE attrelid=('public.'||t)::regclass AND attnum>0 AND NOT attisdropped LOOP IF NOT d ? a.attname THEN RAISE EXCEPTION '字段缺少中文注释：%.%',t,a.attname; END IF; EXECUTE format('COMMENT ON COLUMN %I.%I IS %L',t,a.attname,d->>a.attname); END LOOP; END LOOP; END $$;
COMMENT ON TABLE service_spaces IS '租户品牌或项目的会话服务范围'; COMMENT ON TABLE agent_groups IS '客服组织业务分组'; COMMENT ON TABLE agent_group_members IS '业务组成员关联'; COMMENT ON TABLE routing_pools IS '接待候选集合及分配策略'; COMMENT ON TABLE routing_pool_members IS '固定候选池成员及权重'; COMMENT ON TABLE access_links IS '对外接入链接与页面路由绑定';
COMMENT ON TABLE contact_categories IS '客户主要分类'; COMMENT ON TABLE tag_categories IS '客户标签分类'; COMMENT ON TABLE tags IS '客户可多选标签'; COMMENT ON TABLE contacts IS '租户客户档案及资料可信度'; COMMENT ON TABLE contact_tags IS '客户标签去重关联'; COMMENT ON TABLE contact_field_definitions IS '租户客户自定义字段字典'; COMMENT ON TABLE visitor_sessions IS '独立访客高熵凭证摘要'; COMMENT ON TABLE contact_visits IS '按客户串联的来源与访问轨迹'; COMMENT ON TABLE block_rules IS '保留历史的客户封禁规则';
COMMENT ON TABLE agent_runtime IS '客服在线租期和全池共享接待占用'; COMMENT ON TABLE conversations IS '有独立边界的客户咨询'; COMMENT ON TABLE conversation_assignments IS '咨询正式接待与分配历史'; COMMENT ON TABLE transfer_requests IS '保留原客服的待确认转接'; COMMENT ON TABLE agent_capacity_holds IS '正式接待及转接目标容量占用'; COMMENT ON TABLE attachments IS '受租户权限保护的消息附件'; COMMENT ON TABLE messages IS '幂等持久化聊天消息'; COMMENT ON TABLE conversation_events IS '按授权游标补拉的可靠会话事件'; COMMENT ON TABLE read_cursors IS '多设备共享累计已读'; COMMENT ON TABLE outbox_jobs IS '与事件同事务提交的至少一次实时投递任务'; COMMENT ON TABLE chat_commands IS '带请求摘要的幂等业务动作结果'; COMMENT ON TABLE chat_ws_tickets IS '一次性实时连接鉴权票据';
